def run_capture(prompts, layers, kinds=('mlp_in','resid','attn_in')):
    caps=[]
    for p in prompts:
        ids = tok(harness.chat_format(p),return_tensors='pt')['input_ids']
        store={}
        hds=[]
        for L in layers:
            lay=model.model.layers[L]
            hds.append(lay.post_attention_layernorm.register_forward_hook(lambda m,i,o,L=L: store.__setitem__(('mlp_in',L), o[0].numpy().copy())))
            hds.append(lay.input_layernorm.register_forward_hook(lambda m,i,o,L=L: store.__setitem__(('attn_in',L), o[0].numpy().copy())))
            hds.append(lay.register_forward_hook(lambda m,i,o,L=L: store.__setitem__(('resid',L), (o[0] if isinstance(o,tuple) else o)[0].numpy().copy())))
        try: model(ids)
        finally:
            for h in hds: h.remove()
